package ru.neverland.townymarket;
import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.io.*;
import org.bukkit.configuration.ConfigurationSection;import org.bukkit.configuration.file.YamlConfiguration;import ru.neverland.core.*;
import static ru.neverland.townymarket.MarketData.*;
/** One acknowledged immutable market image. Existing schema1 listings, orders and demand are retained. */
public final class MarketJournal {
 public record Image(Map<UUID,Listing> listings,Map<UUID,Order> orders,List<Demand> demand,Map<UUID,MarketFunding.Payment> payments,List<AuditRecord> audit){
  public Image{listings=Map.copyOf(listings);orders=Map.copyOf(orders);demand=List.copyOf(demand);payments=Map.copyOf(payments);audit=List.copyOf(audit);if(listings.size()>5000||orders.size()>10000||demand.size()>5000||audit.size()>4096)throw new IllegalArgumentException("Архив рынка достиг предела");
   for(var e:listings.entrySet())if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("ID предложения изменён");for(var e:orders.entrySet()){var o=e.getValue();var l=listings.get(o.lot());if(!e.getKey().equals(o.id())||l==null||!l.town().equals(o.seller())||o.city()!=(l.scope()==Scope.GLOBAL))throw new IllegalArgumentException("Покупка не соответствует предложению");if(o.phase()==Phase.DEBIT_READY&&!payments.containsKey(o.id()))throw new IllegalArgumentException("Нет протокола подготовленного списания");}
   for(var e:payments.entrySet()){var o=orders.get(e.getKey());if(o==null)throw new IllegalArgumentException("Нет покупки для платежа");var t=e.getValue().terms();if(t!=null&&(!o.city()||!t.operation().equals(MarketFunding.debit(o.id()))||!t.town().equals(o.buyer())||!t.actor().equals(o.actor())||t.cents()!=o.total()))throw new IllegalArgumentException("Оплата не соответствует покупке");}
   var ids=new HashSet<String>();for(var r:audit)if(!ids.add(r.id()))throw new IllegalArgumentException("Повтор записи аудита");
  }
  public static Image empty(){return new Image(Map.of(),Map.of(),List.of(),Map.of(),List.of());}
 }
 private final Path file;private final AcknowledgedState<Image> state;private java.util.function.Function<Order,AuditRecord> audit=o->null;
 public MarketJournal(Path file){this.file=file;state=new AcknowledgedState<>(file,Image.empty(),MarketJournal::encode,"nlt-market-journal");}
 public void audit(java.util.function.Function<Order,AuditRecord> factory){audit=Objects.requireNonNull(factory);}
 public Image image(){return state.get();}public boolean writable(){return state.writable();}public boolean busy(){return state.busy();}public CompletionStage<Void> close(){return state.prepareClose();}
 public Collection<Listing> listings(){return image().listings().values();}public Collection<Order> orders(){return image().orders().values();}public List<Demand> demand(){return image().demand();}public Listing listing(UUID id){return image().listings().get(id);}public Order order(UUID id){return image().orders().get(id);}
 public void load()throws Exception{if(SuiteState.held())throw new IllegalStateException("Рынок загружается вне общей блокировки");if(!Files.exists(file)){state.loaded(Image.empty());return;}if(Files.size(file)>32L*1024*1024)throw new IOException("Журнал рынка больше 32 МиБ");var y=new YamlConfiguration();y.load(file.toFile());if(y.getInt("schema")!=1&&y.getInt("schema")!=2)throw new IOException("Неизвестная схема рынка");var ls=new LinkedHashMap<UUID,Listing>();var os=new LinkedHashMap<UUID,Order>();var ds=new ArrayList<Demand>();var payments=new LinkedHashMap<UUID,MarketFunding.Payment>();
  var l=section(y,"listings");for(String id:l.getKeys(false)){UUID uuid=UUID.fromString(id);var s=section(l,id);ls.put(uuid,new Listing(uuid,uuid(s,"town"),text(s,"item"),text(s,"label"),text(s,"product"),Scope.valueOf(text(s,"scope")),bool(s,"auto"),num(s,"base"),integer(s,"amount"),num(s,"created"),ListingState.valueOf(text(s,"state")),text(s,"note")));}
  var o=section(y,"orders");for(String id:o.getKeys(false)){UUID uuid=UUID.fromString(id);var s=section(o,id);var order=new Order(uuid,uuid(s,"lot"),uuid(s,"seller"),uuid(s,"buyer"),uuid(s,"actor"),bool(s,"city"),integer(s,"amount"),num(s,"unit"),num(s,"created"),Phase.valueOf(text(s,"phase")),num(s,"check"),text(s,"note"),bool(s,"finalized"),s.contains("revision")?num(s,"revision"):0,s.contains("phase-at")?num(s,"phase-at"):num(s,"created"));os.put(uuid,order);}
  var d=section(y,"demand");for(String id:d.getKeys(false)){var s=section(d,id);ds.add(new Demand(UUID.fromString(id),text(s,"scope"),text(s,"product"),uuid(s,"buyer"),num(s,"at"),integer(s,"amount")));}
  if(y.contains("payments")){var p=section(y,"payments");for(String id:p.getKeys(false)){var s=section(p,id);String protocol=text(s,"protocol");MarketFunding.Terms terms=null;if(protocol.equals("TREASURY"))terms=new MarketFunding.Terms(uuid(s,"operation"),uuid(s,"town"),uuid(s,"actor"),num(s,"cents"),text(s,"category"),text(s,"reason"));payments.put(UUID.fromString(id),new MarketFunding.Payment(protocol,terms));}}
  if(y.contains("audit-outbox")&&!y.isList("audit-outbox"))throw new IOException("Повреждён исходящий журнал рынка");var rows=new ArrayList<AuditRecord>();for(Object row:y.getList("audit-outbox",List.of())){if(!(row instanceof List<?> fields)||fields.stream().anyMatch(v->!(v instanceof String)))throw new IOException("Повреждена строка аудита");rows.add(AuditRecord.parse(fields.stream().map(String.class::cast).toList()));}state.loaded(new Image(ls,os,ds,payments,rows));
 }
 public CompletionStage<Image> commit(Image before,Image next){return state.commit(before,next);}
 public CompletionStage<Listing> put(Listing l){try(var guard=SuiteState.guard()){var before=image();var ls=new HashMap<>(before.listings());ls.put(l.id(),l);return commit(before,new Image(ls,before.orders(),before.demand(),before.payments(),before.audit())).thenApply(v->l);}}
 public CompletionStage<Order> put(Order o){return put(o,null,System.currentTimeMillis());}
 public CompletionStage<Order> put(Order o,MarketFunding.Payment payment,long now){try(var guard=SuiteState.guard()){var before=image();var os=new HashMap<>(before.orders());var prior=os.put(o.id(),o);if(prior!=null&&(!prior.lot().equals(o.lot())||!prior.seller().equals(o.seller())||!prior.buyer().equals(o.buyer())||!prior.actor().equals(o.actor())||prior.city()!=o.city()||prior.amount()!=o.amount()||prior.unit()!=o.unit()||prior.created()!=o.created()))throw new IllegalArgumentException("Условия покупки изменены");if(prior!=null)transition(prior,o);var ps=new HashMap<>(before.payments());if(payment!=null){var old=ps.putIfAbsent(o.id(),payment);if(old!=null&&!old.equals(payment))throw new IllegalArgumentException("Протокол оплаты уже сохранён");}var ds=new ArrayList<>(before.demand().stream().filter(d->d.at()>now-DAY).toList());if(o.phase()==Phase.COMPLETE&&(prior==null||prior.phase()!=Phase.COMPLETE)&&ds.stream().noneMatch(d->d.order().equals(o.id()))){var l=before.listings().get(o.lot());ds.add(new Demand(o.id(),l.scopeKey(),l.product(),o.buyer(),now,o.amount()));}ds.sort(Comparator.comparingLong(Demand::at));if(ds.size()>5000)ds=new ArrayList<>(ds.subList(ds.size()-5000,ds.size()));var rows=new ArrayList<>(before.audit());var record=prior==null||prior.revision()!=o.revision()?audit.apply(o):null;if(record!=null){var found=rows.stream().filter(r->r.id().equals(record.id())).findFirst().orElse(null);if(found==null)rows.add(record);else if(!found.identity().equals(record.identity()))throw new IllegalArgumentException("Конфликт квитанции рынка");}return commit(before,new Image(before.listings(),os,ds,ps,rows)).thenApply(v->o);}}
 public CompletionStage<Void> prune(){try(var guard=SuiteState.guard()){var before=image();var os=new HashMap<>(before.orders());var done=os.values().stream().filter(Order::finalized).sorted(Comparator.comparingLong(Order::created).reversed()).toList();if(done.size()<=2000)return CompletableFuture.completedFuture(null);done.subList(2000,done.size()).forEach(o->os.remove(o.id()));var ps=new HashMap<>(before.payments());ps.keySet().retainAll(os.keySet());return commit(before,new Image(before.listings(),os,before.demand(),ps,before.audit())).thenApply(v->null);}}
 public CompletionStage<Void> removeListing(UUID id){try(var guard=SuiteState.guard()){var before=image();if(before.orders().values().stream().anyMatch(o->o.lot().equals(id)))return CompletableFuture.completedFuture(null);var ls=new HashMap<>(before.listings());ls.remove(id);return commit(before,new Image(ls,before.orders(),before.demand(),before.payments(),before.audit())).thenApply(v->null);}}
 public CompletionStage<Void> auditAck(String id){try(var guard=SuiteState.guard()){var before=image();return commit(before,new Image(before.listings(),before.orders(),before.demand(),before.payments(),before.audit().stream().filter(r->!r.id().equals(id)).toList())).thenApply(v->null);}}
 private static void transition(Order old,Order next){
  if(old.finalized()&&!old.equals(next))throw new IllegalArgumentException("Покупка уже завершена");
  if(old.phase()==next.phase()){if(old.revision()!=next.revision()||old.phaseAt()!=next.phaseAt())throw new IllegalArgumentException("Квитанция этапа изменена");return;}
  if(next.revision()!=Math.addExact(old.revision(),1)||next.phaseAt()<=old.phaseAt())throw new IllegalArgumentException("Устаревший результат покупки");
  boolean allowed=switch(old.phase()){case PREPARED->Set.of(Phase.DEBIT_READY,Phase.RETURNING).contains(next.phase());case DEBIT_READY->Set.of(Phase.DEBIT_PENDING,Phase.RETURNING).contains(next.phase());case DEBIT_PENDING->Set.of(Phase.PAID,Phase.RETURNING).contains(next.phase());case PAID->next.phase()==Phase.DELIVERED;case DELIVERED->next.phase()==Phase.CREDIT_PENDING;case CREDIT_PENDING->Set.of(Phase.COMPLETE,Phase.DELIVERED).contains(next.phase());case RETURNING->next.phase()==Phase.CANCELLED;case COMPLETE,CANCELLED->false;};
  if(!allowed)throw new IllegalArgumentException("Решение не соответствует этапу покупки");
 }
 private static String encode(Image image)throws IOException{var y=new YamlConfiguration();y.set("schema",2);y.createSection("listings");y.createSection("orders");y.createSection("demand");for(var l:image.listings().values()){var s=y.createSection("listings."+l.id());s.set("town",l.town().toString());s.set("item",l.item());s.set("label",l.label());s.set("product",l.product());s.set("scope",l.scope().name());s.set("auto",l.auto());s.set("base",l.base());s.set("amount",l.amount());s.set("created",l.created());s.set("state",l.state().name());s.set("note",l.note());}
  for(var o:image.orders().values()){var s=y.createSection("orders."+o.id());s.set("lot",o.lot().toString());s.set("seller",o.seller().toString());s.set("buyer",o.buyer().toString());s.set("actor",o.actor().toString());s.set("city",o.city());s.set("amount",o.amount());s.set("unit",o.unit());s.set("created",o.created());s.set("phase",o.phase().name());s.set("check",o.check());s.set("note",o.note());s.set("finalized",o.finalized());s.set("revision",o.revision());s.set("phase-at",o.phaseAt());}
  for(var d:image.demand()){var s=y.createSection("demand."+d.order());s.set("scope",d.scope());s.set("product",d.product());s.set("buyer",d.buyer().toString());s.set("at",d.at());s.set("amount",d.amount());}
  for(var e:image.payments().entrySet()){var s=y.createSection("payments."+e.getKey());var p=e.getValue();s.set("protocol",p.protocol());if(p.terms()!=null){var t=p.terms();s.set("operation",t.operation().toString());s.set("town",t.town().toString());s.set("actor",t.actor().toString());s.set("cents",t.cents());s.set("category",t.category());s.set("reason",t.reason());}}
  y.set("audit-outbox",image.audit().stream().map(AuditRecord::fields).toList());String text=y.saveToString();if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>32L*1024*1024)throw new IOException("Журнал рынка больше 32 МиБ");return text;
 }
 private static ConfigurationSection section(ConfigurationSection s,String k)throws IOException{var v=s.getConfigurationSection(k);if(v==null)throw new IOException("Нет раздела "+k);return v;}private static String text(ConfigurationSection s,String k)throws IOException{if(!s.isString(k))throw new IOException("Нет строки "+k);return s.getString(k);}private static UUID uuid(ConfigurationSection s,String k)throws IOException{return UUID.fromString(text(s,k));}private static long num(ConfigurationSection s,String k)throws IOException{if(!(s.get(k) instanceof Number n))throw new IOException("Нет целого "+k);try{return new java.math.BigDecimal(n.toString()).longValueExact();}catch(RuntimeException e){throw new IOException("Нет целого "+k,e);}}private static int integer(ConfigurationSection s,String k)throws IOException{return Math.toIntExact(num(s,k));}private static boolean bool(ConfigurationSection s,String k)throws IOException{if(!s.isBoolean(k))throw new IOException("Нет флага "+k);return s.getBoolean(k);}
}
